        [UnityTest]public IEnumerator ActualSerialCraftingShowsFullPriceRejectsPartialAndSavesBeforeAnimation()
        {
            Debug.Log("PREPARED_W07_UI: isolated funded normal save, real batches3/10/100 and reload; same batch rules as V3, not V3 file migration.");game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Data=ScientificNumber.From(1e12);n.Workshop.components=Enumerable.Repeat(1000000L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.modules=Enumerable.Repeat(10000L,ItemBalance.Modules.Length).ToArray();n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.nodes=new[]{"W07"};n.Research[Array.FindIndex(Balance.Research,d=>d.Id=="blueprints")]=1;return n;});game.enabled=false;game.Show("items");yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Array.FindIndex(ItemBalance.Items,d=>d.Id=="quantum-chip"));var selector=GameObject.Find("BatchQuantity").GetComponent<UnityEngine.UI.Button>();
            foreach(int quantity in new[]{3,10,100}){selector.onClick.Invoke();yield return null;var q=Workshop.BatchQuote(game.State,"quantum-chip",quantity);Assert.That(q.Allowed,Is.True);Assert.That(selector.GetComponentInChildren<UnityEngine.UI.Text>().text,Is.EqualTo("×"+quantity));Assert.That(ui.Primary.GetComponentInChildren<UnityEngine.UI.Text>().text,Does.Contain("×"+quantity));var costs=ui.CostView.GetComponentsInChildren<UnityEngine.UI.Text>();var required=q.Components.Where(n=>n>0).Concat(new[]{q.Data}).ToArray();Assert.That(costs.Length,Is.EqualTo(required.Length));for(int c=0;c<required.Length;c++)Assert.That(costs[c].text,Does.EndWith("/"+NumberFormatting.Format(ScientificNumber.From(required[c]),game.State.Settings.numberFormat,game.State.Settings.language)),"full batch price");
                if(quantity==3){var stocked=(long[])game.State.Workshop.components.Clone();int c=Array.FindIndex(q.Components,n=>n>0);game.Act(s=>{var n=s.Copy();n.Workshop.components[c]=(long)q.Components[c]-1;n.Workshop.revision++;return n;});yield return null;Assert.That(ui.Primary.interactable,Is.False,"unit affordable, full batch unavailable");var before=File.ReadAllText(game.SavePath);int count=game.State.Workshop.inventory.Length;ui.Commit();Assert.That(File.ReadAllText(game.SavePath),Is.EqualTo(before));Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(count));game.Act(s=>{var n=s.Copy();n.Workshop.components=stocked;n.Workshop.revision++;return n;});yield return null;}
                Assert.That(ui.Primary.interactable,Is.True);int oldCount=game.State.Workshop.inventory.Length;ui.Primary.onClick.Invoke();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(oldCount+quantity));var saved=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(saved.Writable,Is.True,saved.Message);Assert.That(saved.State.Workshop.inventory.Length,Is.EqualTo(oldCount+quantity),"full result saved before effect ends");Assert.That(ui.Forge.IsAnimating,Is.True);Assert.That(ui.Forge.PresentedCount,Is.EqualTo(quantity),"one shared batch result");if(quantity==3){float end=Time.realtimeSinceStartup+6;while(ui.Forge.IsAnimating&&Time.realtimeSinceStartup<end)yield return null;Assert.That(ui.Forge.IsAnimating,Is.False,"first batch finishes without a next action");}else ui.Forge.Cancel();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(oldCount+quantity));}
            Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(113));game.Act(s=>{var n=s.Copy();n.Workshop.nodes=Array.Empty<string>();n.Workshop.revision++;return n;});yield return null;Assert.That(selector.GetComponentInChildren<UnityEngine.UI.Text>().text,Is.EqualTo("×1"),"lost W07 restores usable single craft");Assert.That(selector.interactable,Is.False);Assert.That(ui.Primary.interactable,Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(113));Assert.That(game.State.Workshop.inventory.Select(i=>i.id).Distinct().Count(),Is.EqualTo(113));Assert.That(game.State.ItemSystemV3,Is.Null);
        }
