                game.Show("research");game.SetResearchArea(0);yield return null;yield return null;yield return null;game.FlushLocalization();Canvas.ForceUpdateCanvases();var card=GameObject.Find("research-dataGeneration").GetComponent<LearningCard>();Assert.That(card.Duration.text,Is.EqualTo(LearningPresentation.Remaining(.5,locale,true)),locale+" actual frozen floor after removing protocol");Assert.That(card.Duration.preferredHeight,Is.LessThanOrEqualTo(card.Duration.rectTransform.rect.height+1),locale+" remaining duration fits");Assert.That(card.Progress.fillAmount,Is.EqualTo(1),"prepared full work does not imply early completion");WorkshopTests.Capture(width,Screen.height,output+"/research-floor-"+locale+"-"+width+".png");foreach(string type in new[]{"protocol-controller","experiment-controller","lab-drone"}){game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");var item=state.Workshop.inventory.First(i=>i.type==type);game.WorkshopView.OpenItem(item.id);game.FlushLocalization();yield return null;yield return new WaitForSecondsRealtime(.35f);Canvas.ForceUpdateCanvases();var text=game.WorkshopView.DetailText;Assert.That(text.preferredHeight,Is.LessThanOrEqualTo(text.rectTransform.rect.height+1),locale+" "+type+" primary and real comparisons fit");Assert.That(ItemV3ResearchDetails.Copy(state,"slots"),Does.Not.Contain("{"),locale+" real balance in slot explanation");if(type!="protocol-controller")Assert.That(GameObject.Find("Unequip").GetComponentInChildren<UnityEngine.UI.Text>().text,Is.EqualTo(new[]{"Unequip","Ablegen","Quitar","Retirer","Desequipar","Rimuovi","Zdejmij"}[Array.IndexOf(SettingsCatalog.Languages,locale)]),locale+" unequip action localized");if(type=="protocol-controller"){Assert.That(text.text,Does.Contain("#FF929B"),"raising minimum duration must show the real drawback");Assert.That(text.text,Does.Contain(.001.ToString("0.###",System.Globalization.CultureInfo.GetCultureInfo(locale))));}WorkshopTests.Capture(width,Screen.height,output+"/"+type+"-"+locale+"-"+width+".png");}Assert.That(File.ReadAllText(game.SavePath),Is.EqualTo(saved),"read-only V3 never overwrites normal original");}
            }}finally{property.SetValue(game,original);lifecycle.SetValue(game,started);game.enabled=true;game.Show("hardware");}
        }
